const runId = $('Input').first().json.run_id;
const rows = $input.all().map(i => i.json).filter(r => r && r.run_id === runId);

if (!rows.length) {
  return [{ json: { run_id: runId, error: 'No fan-out run found with this run_id. Check the run_id returned by fan_out.' } }];
}

const completed = rows.filter(r => r.status === 'complete');
const errors = rows.filter(r => r.status === 'error');
const pending = rows.filter(r => r.status === 'pending');
const done = pending.length === 0;

return [{
  json: {
    run_id: runId,
    done,
    total_items: rows.length,
    completed: completed.length,
    errors: errors.length,
    pending: pending.length,
    hint: done ? undefined : ('Not finished — ' + pending.length + ' item(s) still processing. Call wait for 60 seconds, then call fan_out_results again with the same run_id.'),
    results: rows
      .filter(r => r.status !== 'pending')
      .sort((a, b) => (a.item_index ?? 0) - (b.item_index ?? 0))
      .map(r => {
        let item = r.item;
        if (typeof item === 'string') { try { item = JSON.parse(item); } catch (e) {} }
        return { item_index: r.item_index, item, status: r.status, response: r.response };
      })
  }
}];
